entries[221549] = { ["name"] = "Wastewander Cipher", ["text"] = "\"Aids in the translation of documents written by Wastewander Bandits.\"" }
entries[221780] = { ["name"] = "Princess Theradras' Scepter", ["text"] = "Binds when picked up\nTwo-Hand Mace\n111 - 174 Damage Speed 3.40\n(41.91 damage per second)\n90 Armor\n+13 Strength\n+10 Agility\n+15 Stamina\n+9 Spirit\nDurability 100 / 100\nRequires Level 46\nEquip: +67 Attack Power in Cat, Bear, and Dire Bear forms only." }
entries[221781] = { ["name"] = "Avenguard Helm", ["text"] = "Binds when picked up\nHead Plate\n469 Armor\n+10 Strength\n+5 Agility\n+25 Stamina\nDurability 80 / 80" }
entries[221782] = { ["name"] = "Helm of Exile", ["text"] = "Binds when picked up\nHead Mail\n266 Armor\n+11 Agility\n+18 Intellect\nDurability 70 / 70\nEquip: +36 Attack Power." }
entries[221783] = { ["name"] = "Lawbringer Spaulders", ["text"] = "Binds when picked up\nShoulder Plate\n562 Armor\n+17 Strength\n+15 Stamina\n+7 Fire Resistance\nDurability 100 / 100\nClasses: Paladin\nRequires Level 60\nEquip: Increases damage done by Holy spells and effects by up to 21.\nEquip: Improves your chance to hit with all spells and attacks by 1%.\n\nLawbringer Radiance (0/8)\nLawbringer Battleboots\nLawbringer Breastplate\nLawbringer Crown\nLawbringer Girdle\nLawbringer Grips\nLawbringer Leggings\nLawbringer Spaulders\nLawbringer Warbands\n(2) Set : Your Judgement of Light and Judgement of Wisdom also grant the effects of Judgement of the Crusader.\n(4) Set : Increases your critical strike chance with spells and attacks by 2%.\n(6) Set : Your Seal of Command, Seal of Righteousness, Seal of Martyrdom, and Sunlight deal 35% less damage, but now persist for 6 seconds after you cast another Seal, or until you cast a third Seal. Your Judgements can now trigger multiple Seals if active." }
entries[221785] = { ["name"] = "Cenarion Vestments", ["text"] = "Binds when picked up\nChest Leather\n200 Armor\n+11 Stamina\n+17 Intellect\n+15 Spirit\n+10 Fire Resistance\nDurability 120 / 120\nClasses: Druid\nRequires Level 60\nEquip: Increases healing done by spells and effects by up to 62.\n\nCenarion Bounty (0/8)\nCenarion Belt\nCenarion Boots\nCenarion Bracers\nCenarion Gloves\nCenarion Helm\nCenarion Leggings\nCenarion Spaulders\nCenarion Vestments\n(2) Set : When you cast Innervate on another player, it is also cast on you.\n(4) Set : Casting your Healing Touch or Nourish spells gives you a 25% chance to gain Mana equal to 35% of the base cost of the spell. (Proc chance: 25%, 1s cooldown)\n(6) Set : Reduces the cooldown on Tranquility by 100% and increases its healing by 100%. (Proc chance: 25%, 1s cooldown)" }
entries[221971] = { ["name"] = "Dreamsworn Horn", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Combine the collected reagents into a rune that will teach a new Engraving spell.\n\"A unique reagent that carries a fiery essence. A new rune may be crafted if you find other similar components.\"" }
entries[221972] = { ["name"] = "Dreampyre Fire", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Combine the collected reagents into a rune that will teach a new Engraving spell.\n\"A unique reagent that carries a fiery essence. A new rune may be crafted if you find other similar components.\"" }
