entries[224893] = { ["name"] = "Overcharged Portal Tuner", ["text"] = "Use: Connect a Fel Scar or Rift to a world deep in Legion space. May have unpredictable and dangerous effects.\n2 Charges" }
entries[224912] = { ["name"] = "Portal Tuner Tuner", ["text"] = "Use: Overcharge a Legion Portal Tuner." }
entries[225675] = { ["name"] = "Sooty Obsidian Core", ["text"] = "Binds when picked up\nUnique\nUse: Polish off the soot." }
entries[225676] = { ["name"] = "Molten Obsidian Core", ["text"] = "Binds when picked up\nUnique\nDuration: 10 min (real time)\n\"Cool it down before it melts!\"" }
entries[225686] = { ["name"] = "Rune of Decimation", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your boots with the Decimation rune:\n\nYour Soul Fire spell no longer has a cooldown. Additionally, when your Shadow Bolt, Shadow Cleave, Incinerate, or Soul Fire hits a target that is at or below 35% health, the cast time of your Soul Fire spell is reduced by 40% for 10 sec. Soul Fires cast under the effect of Decimation cost no shard.\n\"Teaches you a new Engraving ability.\"" }
entries[225687] = { ["name"] = "Rune of Infernal Armor", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your cloak with the Infernal Armor rune:\n\nYour spirit becomes infused with demonic energy, reducing all Magic damage you take by a percentage equal to 60% of your Physical damage reduction from armor. Lasts 10 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[225688] = { ["name"] = "Rune of Mark of Chaos", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your cloak with the Mark of Chaos rune:\n\nAll your Curses except Curse of Shadow and Curse of the Elements now apply the Mark of Chaos, reducing the target's Arcane, Fire, Frost, Nature, and Shadow resistances by [Max(Min( 56 + 19, 75), 27)] and increasing all spell damage taken from those schools by [Max(Min(( 56 - 8) * 0.125 + 4, 10), 4)]% while they remain cursed.\n\"Teaches you a new Engraving ability.\"" }
entries[225689] = { ["name"] = "Spell Notes: Arcane Barrage", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your cloak with the Arcane Barrage rune:\n\nLaunches several missiles at the enemy target, causing [source value] to [source value] Arcane damage. This spell also has a 25% to trigger Missile Barrage.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[225690] = { ["name"] = "Spell Notes: Frozen Orb", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your cloak with the Frozen Orb\nrune:\n\nLaunches an orb of swirling ice which rapidly moves forward over 16 sec. While it is moving, every 1 sec the orb deals [source value] Frost Damage and applies a Chill for 30% movement speed reduction to all enemies it passes through. The first time it damages an enemy, its movement will slow and it will have a 100% chance to trigger the Fingers of Frost rune.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[225691] = { ["name"] = "Spell Notes: Overheat", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your cloak with the Overheat rune:\n\nFire Blast will always deal a critical strike, can be cast while casting another spell, and is not affected by the global cooldown, but its cooldown is increased to 15 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[225740] = { ["name"] = "Rune of Composure", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your cloak with the Coherence rune:\n\nCauses your Chain heal effectiveness to only reduce by 35% per jump, and Chain Lightning effectiveness to only reduce by 20% per jump. Each also jumps to 1 additional target.\n\"Teaches you a new Engraving ability.\"" }
entries[225838] = { ["name"] = "Voltaic Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nEngrave your cloak with the Storm, Earth, and Fire rune:\n\nReduces the cooldown of your Chain Lightning by 25%, causes your Earthbind Totem to root targets for 5 sec when cast, and increases the periodic damage done by your Flame Shock by 60%.\n\"Learn a new ability after defeating 3 enemies with a single cast of Chain Lightning.\"" }
entries[225893] = { ["name"] = "Epoch's End", ["text"] = "Binds when picked up\nUnique: (Unknown #636) (0)\nTwo-Hand Sword\n300 - 415 Damage Speed 4.20\n(85.12 damage per second)\n-322 Stamina\nDurability 120 / 120\nRequires Level 77" }
entries[225914] = { ["name"] = "Rune of the Bound Spirit", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your cloak with the Feral Spirit rune:\n\nSummons two Spirit Wolves under the command of the Shaman, lasting 45 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[225929] = { ["name"] = "Plagued Soul Shard", ["text"] = "Binds when picked up\nUnique (3)" }
entries[225938] = { ["name"] = "Torn Spell Notes", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nUse: Combine the collected Torn Spell Notes into a scroll that will teach a new Engraving spell.\n\"An incomplete page that appears similar to scrolls that teach Engraving abilities. Three-quarters are missing.\"" }
